def icon(name):
    paths={'new':'<path d="M8 2v12M2 8h12"/>','open':'<path d="M1 13V3h5l2 3h7l-2 7Z"/>','save':'<rect x="2" y="1" width="12" height="14" rx="1"/><path d="M5 1v5h6V1M5 15v-5h6v5"/>','sidebar':'<rect x="1" y="2" width="14" height="12" rx="2"/><path d="M6 2v12"/>','refresh':'<path d="M13 6a6 6 0 1 0 0 5M14 1v5H9"/>'}
    return '<span class="icon"><svg viewBox="0 0 16 16">'+paths[name]+'</svg></span>'

def toggle(label,on):return f'<div class="setting-row"><span>{label}</span><span class="switch {"on" if on else ""}"></span></div>'
def select(text):return f'<span class="select">{text}</span>'
def button(text,kind=''):return f'<button class="{kind}">{text}</button>'
def footer(*buttons):return '<div class="dialog-footer">'+''.join(buttons)+'</div>'

def preferences(bottom=False):
    first=f'''<div class="row spread"><b>MDcard 0.1.0</b><span class="small muted">设置即时生效</span></div><div class="section">语言</div>{select('简体中文')}<div class="description">语言更改会立即生效。</div><div class="rule"></div><div class="section">外观</div><div class="row">{button('浅色','selected')}{button('深色')}{button('跟随系统')}</div><div class="section">强调色</div><div class="swatches">'''+''.join(f'<span class="swatch {"active" if i==0 else ""}" style="--c:{c}"></span>' for i,c in enumerate(['#3a569d','#7844b7','#b72e6e','#a55311','#217849','#555e70']))+f'''</div>{toggle('减少动画',True)}<div class="rule"></div><div class="section">文字大小</div><div class="row spread"><span class="slider"></span>{select('15.0 px')}</div><div class="rule"></div>'''
    second=f'''{toggle('自动保存',False)}<div class="description">停止编辑 2 秒后写入原文件；未命名文档需先手动保存。</div>{toggle('崩溃恢复',True)}<div class="description">保留独立的本地恢复副本；关闭后不会删除待恢复副本。</div><div class="rule"></div><div class="section">性能</div>{toggle('GPU 加速',True)}<div class="description">更改将在下次打开 MDcard 时生效。</div><div class="small">当前：OpenGL（已请求加速）</div><div class="description">Mesa llvmpipe · 软件 OpenGL</div><div class="rule"></div><div class="section">阅读位置</div><div class="path">/work/evidence/ui-ux/2026-10-28/sessions/reading.json</div><div class="row" style="margin-top:10px">{button('清除此文档的阅读位置')}{button('清除所有阅读位置')}</div>'''
    return f'<div class="dialog"><div class="dialog-title">偏好设置</div><div class="dialog-body" style="height:600px">{second if bottom else first+second}<div class="scrollhint"></div></div>{footer(button("完成","primary"))}</div>'

def dialog(kind):
    if kind in ['preferences','preferences-bottom']:return '<div class="backdrop">'+preferences(kind.endswith('bottom'))+'</div>'
    if kind=='unsaved':return '<div class="backdrop"><div class="dialog" style="width:440px"><div class="dialog-title">保存更改？</div><p>“未命名.md” 有未保存的更改。请在继续前保存。</p>'+footer(button('取消'),button('不保存'),button('保存更改','primary'))+'</div></div>'
    if kind=='rename':return '<div class="backdrop"><div class="dialog" style="width:440px"><div class="dialog-title">重命名文档…</div><div class="description">同一文件夹中的新文件名</div><div class="input focus">工作札记.md</div>'+footer(button('重命名','primary'),button('取消'))+'</div></div>'
    if kind=='error':return '<div class="backdrop"><div class="dialog" style="width:460px"><div class="dialog-title">需要处理的问题</div><p>无法打开文档。</p><div class="description">文件字节不符合所选编码。请选择其他编码重新打开。</div><div class="small muted">资源：invalid.md</div>'+footer(button('确定','primary'))+'</div></div>'
