    if kind=='quick':
        body='<div class="input focus">开发</div><div class="description" style="margin:12px 0">↑ ↓ 选择 · Enter 打开 · Shift+Enter 并排打开 · Esc 关闭</div><div class="list-row active"><span>开发笔记.md</span><span class="small">开发笔记</span></div>'
        return window('快速切换 · Ctrl+P',body,650,150)
    if kind=='search':
        body='<div class="row">'+button('当前文档','selected')+button('工作区')+button('替换快照','flat')+'</div><div class="section">fixtures</div><div class="row"><div class="input focus" style="flex:1">内容</div>'+button('Aa','flat')+button('ab','flat')+button('.*','flat')+'</div><div class="row" style="margin:12px 0"><span>替换为</span><div class="input" style="flex:1;height:40px;color:var(--muted)">$1 · $2 · $&lt;name&gt;</div></div><div class="row">'+button('预览更改')+button('刷新')+button('取消搜索')+'<span class="small muted">6 · 2.3 ms</span></div><div class="rule"></div><div class="small muted">2 个匹配项</div><div class="list-row"><b>⌄ 工作札记.md (2)</b></div><div class="list-row">11: 检查交付细节与内容</div><div class="list-row">13: 好的工具让内容自然成为中心。</div>'
        return window('查找与替换',body,760,100,560)
    if kind=='export':
        body='<div class="section" style="margin-top:0">源文档</div><div class="path">/work/evidence/ui-ux/2026-10-28/fixtures/工作札记.md</div><div class="description">导出当前文档的快照。你可以继续编辑。</div><div class="rule"></div><div class="formgrid"><span>导出格式</span>'+select('PDF 文档')+'<span>主题</span>'+select('当前编辑器主题')+'<span>纸张</span>'+select('A4')+'</div><div class="description" style="margin:12px 0">内置管线 · 随包运行时</div><div class="rule"></div><div class="row spread"><span>字号 '+select('16.0')+'</span><span>边距 (mm) '+select('18.0')+'</span><span>图片倍率 '+select('2.0')+'</span></div><div class="row" style="margin:14px 0"><span>☑ 可点击目录</span><span>☑ 代码行号</span></div><div class="rule"></div><div class="list-row">▸ 文档元数据</div><div class="list-row">▸ 自定义 CSS</div><div class="list-row">▸ Pandoc 配置</div>'+footer(button('导出…','primary'))
        return window('导出文档',body,640,110)
    if kind=='structure':
        body='<div class="row">'+button('表格','selected')+button('块')+button('插入表格','flat')+button('返回源码','flat')+'</div><div class="description" style="margin-top:12px">Tab / Shift+Tab 移动 · Ctrl+S 保存 · Ctrl+Z 撤销</div><div class="rule"></div><div class="row">'+select('表格 1')+button('新增行')+button('新增列')+button('复制 Markdown')+'</div><div class="description">编辑会同步到 Markdown；Tab / Shift+Tab 移动单元格。</div><table style="width:100%;border-collapse:separate;border-spacing:8px"><tr><td class="input">区域</td><td class="input">目的</td></tr><tr><td class="input">导航</td><td class="input">找到手边的文档</td></tr><tr><td class="input">编辑</td><td class="input">专注表达与思考</td></tr><tr><td class="input">阅读</td><td class="input">看见完整的内容</td></tr></table>'
        return window('结构操作',body,710,130,440)
    if kind=='recovery':
        body='<div class="description" style="margin-top:0">恢复将打开新的未保存副本，不会写入原文件。</div><div class="rule"></div><b>开发笔记.md</b><div class="path" style="margin:8px 0">/work/evidence/ui-ux/2026-10-28/fixtures/开发笔记.md</div><div class="small muted">主文档 · UTF-8 · 无 BOM</div><div class="codecell" style="margin:12px 0"># 开发笔记<br>记录一个可落地的想法。<br>独立恢复副本待验收</div><div class="row">'+button('恢复','primary')+button('删除恢复副本…')+'</div>'+footer(button('稍后处理'))
        return window('恢复稿件…',body,650,130)
    if kind=='history':return window('替换快照','<div class="description">回滚前会核查当前磁盘和已打开缓冲区，再恢复原始字节。</div><div class="rule"></div><div class="muted">没有替换快照。</div>',600,150,220)
