    sidebar='<div class="sidebar"><div class="folder-title">fixtures<div class="tools">'+icon('open')+icon('refresh')+'</div></div><div class="tabs"><span class="tab active">文件</span><span class="tab">大纲</span><span class="tab">最近</span></div><div class="count">6 个支持的文件</div><div class="tree"><span class="muted">⌄</span> ▱ &nbsp;fixtures</div>'+''.join(f'<div class="tree child {"selected" if label=="工作札记.md" else ""}"><span class="file">▯</span>{label}</div>' for label in ['empty.md','invalid.md','long-document.md','工作札记.md','开发笔记.md','这是一个用于验证标题截断与路径…'])+'</div>'
