SCENARIOS=[('01-main-split','split',1240,820),('02-write','write',1240,820),('03-read','read',1240,820),('04-dark','dark',1240,820),('05-narrow','narrow',680,480),('06-empty','empty',1240,820),('07-longname','longname',1240,820),('08-preferences','preferences',1240,820),('09-preferences-bottom','preferences-bottom',1240,820),('10-preferences-narrow','preferences-narrow',680,480),('11-export','export',1240,820),('12-search','search',1240,820),('13-quick','quick',1240,820),('14-structure','structure',1240,820),('15-encoding','encoding',1240,820),('16-unsaved','unsaved',1240,820),('17-error','error',1240,820),('18-rename','rename',1240,820),('19-recovery','recovery',1240,820),('20-secondary','secondary',1240,820),('21-history','history',1240,820),('22-menu','menu',1240,820)]
